<template>
	<v-card class="pt-3">
		<div class="px-3 text-center" v-show="!loading">
			<div>
				<v-avatar size="60">
					<img src="/avatar-user.jpg" alt="">
				</v-avatar>
			</div>
			<h5 class="pt-1 text-h5 ">
				{{ localData ? localData.fullName : '' }}
			</h5>
			<h6 class="pb-2 text-h6 grey--text" v-if="showEdit">
				نام کاربری: <span>&lrm;{{ localData ? localData.userName : '' }}</span>
			</h6>
			<div class="py-1" v-if="showEdit">
				<v-btn dark small color="blue" title="ویرایش اطلاعات" @click="edit">
					<v-icon dark>
						mdi-square-edit-outline
					</v-icon>
